    brightness(1.02);
  box-shadow:
    0 0 14px rgb(185 124 45 / .38),
    inset 0 0 18px rgb(75 43 17 / .22);
  animation: hanok-card-arrive 880ms cubic-bezier(.22,.61,.36,1) both, hanok-card-breathe 7.6s ease-in-out 1.1s infinite alternate;
