.cb-hanok::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 1;
  pointer-events: none;
  -webkit-mask: var(--hanok-edge-mask);
  mask: var(--hanok-edge-mask);
  mix-blend-mode: screen;
  opacity: 0;
  background:
    linear-gradient(108deg, transparent 0 37%, rgb(255 229 160 / 0) 43%, rgb(255 233 177 / .26) 47%, rgb(255 255 245 / .72) 50%, rgb(255 210 122 / .30) 53%, transparent 61% 100%),
    radial-gradient(ellipse at 50% 7%, rgb(255 220 132 / .58) 0, transparent 12%),
    radial-gradient(ellipse at 50% 94%, rgb(255 186 91 / .48) 0, transparent 13%),
    radial-gradient(ellipse at 8% 49%, rgb(255 225 159 / .44) 0, transparent 13%),
    radial-gradient(ellipse at 92% 49%, rgb(255 225 159 / .44) 0, transparent 13%);
  background-size: 285% 100%, 100% 100%, 100% 100%, 100% 100%, 100% 100%;
  background-position: 175% 0, center, center, center, center;
  animation: hanok-edge-sweep 9.5s ease-in-out 1.4s infinite;
}

.cb-hanok::after {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 2;
  pointer-events: none;
  -webkit-mask: var(--hanok-edge-mask);
  mask: var(--hanok-edge-mask);
  mix-blend-mode: screen;
  opacity: var(--hanok-glow-low);
  background:
    radial-gradient(ellipse at 7.5% 8.5%, rgb(245 176 85 / .40) 0, transparent 15%),
    radial-gradient(ellipse at 92.5% 8.5%, rgb(245 176 85 / .40) 0, transparent 15%),
    radial-gradient(ellipse at 7.5% 91%, rgb(44 126 91 / .28) 0, transparent 15%),
    radial-gradient(ellipse at 92.5% 91%, rgb(44 126 91 / .28) 0, transparent 15%),
    radial-gradient(circle, rgb(255 236 174 / .50) 0 1px, transparent 1.6px),
    radial-gradient(circle, rgb(68 150 106 / .32) 0 .8px, transparent 1.4px),
    radial-gradient(circle, rgb(207 79 35 / .25) 0 .8px, transparent 1.35px);
  background-position: center, center, center, center, 9px 18px, 54px 96px, 22px 136px;
  background-size: 100% 100%, 100% 100%, 100% 100%, 100% 100%, 64px 160px, 72px 190px, 86px 210px;
  animation: hanok-local-glow 7.4s ease-in-out infinite alternate, hanok-paper-drift 20s linear infinite;
}

.cb-hanok:is(:hover, :focus-within) {
  --hanok-shine-peak: .64;
  --hanok-glow-low: .26;
  --hanok-glow-high: .60;
  filter:
    drop-shadow(0 0.18rem 0.24rem rgb(39 24 12 / .22))
    drop-shadow(0 0 .44rem rgb(210 150 62 / .24))
    saturate(1.10)
    brightness(1.04);
}

@keyframes hanok-card-arrive {
  0% {
    opacity: 0;
    clip-path: inset(0 49% 0 49%);
    filter: blur(.18rem) saturate(.82);
  }
  48% { opacity: 1; }
  100% {
    opacity: 1;
    clip-path: inset(0);
  }
}

@keyframes hanok-card-breathe {
  0%, 100% { opacity: .96; }
  50% { opacity: 1; }
}

@keyframes hanok-edge-sweep {
  0%, 17% {
    opacity: 0;
    background-position: 175% 0, center, center, center, center;
  }
  23%, 52% { opacity: var(--hanok-shine-peak); }
  66%, 100% {
    opacity: 0;
    background-position: -85% 0, center, center, center, center;
  }
}

@keyframes hanok-local-glow {
  0% {
    opacity: var(--hanok-glow-low);
    transform: scale(.9985);
  }
  100% {
    opacity: var(--hanok-glow-high);
    transform: scale(1.0035);
  }
}

@keyframes hanok-paper-drift {
  0% { background-position: center, center, center, center, 9px 18px, 54px 96px, 22px 136px; }
  100% { background-position: center, center, center, center, 43px -46px, 18px 258px, 94px -74px; }
}

@media (prefers-reduced-motion: reduce) {
  .cb-hanok,
  .cb-hanok::before,
  .cb-hanok::after {
    animation: none;
  }

  .cb-hanok {
    opacity: 1;
    clip-path: none;
  }
}
